/**
 * Words the recognizer is told to expect.
 *
 * A general speech model mishears technical vocabulary — "MCP" becomes "MTP",
 * "grep" becomes "graph". Biasing the recognizer toward terms a developer
 * actually says fixes that, and costs nothing when they are not spoken.
 */
/** Terms every session biases toward, regardless of what the caller asks for. */
export declare const DEFAULT_KEYTERMS: readonly string[];
/**
 * Pack terms into the comma-separated header value the service expects.
 *
 * Commas separate entries, so a comma inside a term would split it in two —
 * they become spaces. Non-ASCII is dropped because the value travels in an
 * HTTP header, where anything outside printable ASCII is not safely
 * transmissible. Duplicates are removed so a caller repeating a default term
 * does not eat the budget twice, and the list is cut at the byte cap rather
 * than sent over-long.
 */
export declare function packKeyterms(terms: readonly string[]): string;
